    """Detect if formula uses integer operations (%, //, Mod)."""
    return bool(re.search(r'(?<![/])%(?!%)|//|\bMod\s*\(', formula_str))


def _ast_rewrite(formula_str: str) -> str:
    """Rewrite chained comparisons and Python and/or/not to Z3 equivalents via AST."""
    try:
        tree = ast.parse(formula_str, mode='eval')
    except SyntaxError:
        return formula_str

    modified = [False]

    class _Rewriter(ast.NodeTransformer):
        def visit_Compare(self, node):
            self.generic_visit(node)
            if len(node.comparators) > 1:
                modified[0] = True
                parts = []
                left = node.left
                for op, comp in zip(node.ops, node.comparators):
                    parts.append(ast.Compare(
                        left=ast.copy_location(left, node),
                        ops=[op],
                        comparators=[comp],
                    ))
                    left = comp
                return ast.Call(
                    func=ast.Name(id='And', ctx=ast.Load()),
                    args=parts, keywords=[],
                )
            return node

        def visit_BoolOp(self, node):
            self.generic_visit(node)
            modified[0] = True
            name = 'And' if isinstance(node.op, ast.And) else 'Or'
            return ast.Call(
                func=ast.Name(id=name, ctx=ast.Load()),
                args=node.values, keywords=[],
            )

        def visit_UnaryOp(self, node):
            self.generic_visit(node)
            if isinstance(node.op, ast.Not):
                modified[0] = True
                return ast.Call(
                    func=ast.Name(id='Not', ctx=ast.Load()),
                    args=[node.operand], keywords=[],
                )
            return node

        def visit_Tuple(self, node):
            self.generic_visit(node)
            if len(node.elts) >= 2 and all(
                isinstance(e, ast.Compare) for e in node.elts
            ):
                modified[0] = True
                return ast.Call(
                    func=ast.Name(id='And', ctx=ast.Load()),
                    args=list(node.elts), keywords=[],
                )
            return node

    tree = _Rewriter().visit(tree)
    if modified[0]:
        ast.fix_missing_locations(tree)
        return ast.unparse(tree)
    return formula_str


