class MaxSATSolver:
    """Weighted partial MAX-SAT solver using z3.Optimize."""

    def solve(self, unique_constraints: list[UniqueConstraint], timeout_ms: int = 10000, hard_timeout_s: int = 60, hard_constraints: list | None = None) -> MaxSATResult:
        """Find the maximum-weight satisfiable subset of constraints."""
        if not unique_constraints:
            return MaxSATResult(satisfied=[], excluded=[], total_weight=0, solve_time_ms=0.0)

        opt = z3.Optimize()
        opt.set("timeout", timeout_ms)

        indicators = []
        active_mask = []
        for i, uc in enumerate(unique_constraints):
            ind = z3.Bool(f"__ind_{i}")
            indicators.append(ind)
            try:
                if not z3.is_bool(uc.z3_formula):
                    active_mask.append(False)
                    continue
                opt.add(z3.Implies(ind, uc.z3_formula))
                opt.add_soft(ind, weight=uc.weight)
                active_mask.append(True)
            except Exception as e:
                logger.debug("Skipping constraint %d in MaxSAT: %s", i, e)
                active_mask.append(False)

        if not any(active_mask):
            return MaxSATResult(satisfied=[], excluded=list(unique_constraints),
                                total_weight=0, solve_time_ms=0.0)

        if hard_constraints:
            for _hc in hard_constraints:
                opt.add(_hc)

        _timed_out = [False]
        def _watchdog():
            _timed_out[0] = True
            z3.main_ctx().interrupt()

        timer = threading.Timer(hard_timeout_s, _watchdog)
        timer.daemon = True
        timer.start()
        t0 = time.perf_counter()
        try:
            result = opt.check()
        finally:
            timer.cancel()
        solve_time = (time.perf_counter() - t0) * 1000

        if _timed_out[0]:
            logger.warning(
                "Z3 MaxSAT hard timeout after %.1fs, returning all constraints as excluded",
                solve_time / 1000,
            )
            return MaxSATResult(
                satisfied=[], excluded=list(unique_constraints),
                total_weight=0, solve_time_ms=solve_time,
            )

        satisfied = []
        excluded = []

        if result in (z3.sat, z3.unknown):
            model = opt.model()
            for i, uc in enumerate(unique_constraints):
                if not active_mask[i]:
                    excluded.append(uc)
                    continue
                val = model.evaluate(indicators[i], model_completion=True)
                if z3.is_true(val):
                    satisfied.append(uc)
                else:
                    excluded.append(uc)
        else:
            excluded = list(unique_constraints)

        total_w = sum(uc.weight for uc in satisfied)
        return MaxSATResult(
            satisfied=satisfied,
            excluded=excluded,
            total_weight=total_w,
            solve_time_ms=solve_time,
        )
